package dev.gbppimentel.zzz;
import java.util.*;
public final class ControllerFocusTest {
 static int checks;static void check(boolean v){if(!v)throw new AssertionError("Controller focus "+checks);checks++;}
 public static void main(String[]args){int[] p=new int[480*270];int yellow=0xffdfed00;for(int x=122;x<=415;x++){p[80*480+x]=yellow;p[128*480+x]=yellow;}for(int y=82;y<=126;y++){p[y*480+120]=yellow;p[y*480+417]=yellow;}for(int[] a:new int[][]{{121,81},{416,81},{121,127},{416,127}})p[a[1]*480+a[0]]=yellow;List<int[]> regions=ControllerFocus.regions(p);check(regions.size()==1);int[] box=regions.get(0);check(box[0]==480&&box[2]==1672&&box[1]==320&&box[3]==516);for(int y=104;y<132;y++)for(int x=42;x<109;x++)p[y*480+x]=0xff1685ed;regions=ControllerFocus.regions(p);check(regions.size()==2);check(ControllerFocus.near(regions,677,375)[0]==480);check(ControllerFocus.near(regions,300,480)[0]==168);check(ControllerFocus.near(Collections.emptyList(),900,800)==null);Arrays.fill(p,0);for(int x=341;x<=415;x++){p[101*480+x]=0xff796c21;p[224*480+x]=0xff796c21;}for(int y=101;y<=224;y++){p[y*480+341]=0xff796c21;p[y*480+415]=0xff796c21;}check(ControllerFocus.regions(p).size()==1);for(int i=0;i<p.length;i++)if(p[i]!=0)p[i]=0xff637a20;check(ControllerFocus.regions(p).size()==1);Arrays.fill(p,0);for(int x=18;x<90;x++){p[235*480+x]=0xff637a20;p[266*480+x]=0xff637a20;}for(int y=235;y<=266;y++){p[y*480+18]=0xff637a20;p[y*480+88]=0xff637a20;}for(int y=240;y<258;y++)for(int x=180;x<235;x++)p[y*480+x]=yellow;check(ControllerFocus.travel(p,true)[0]==72);check(ControllerFocus.travel(p,false)==null);check(ControllerFocus.near(Arrays.asList(new int[]{108,712,440,880,350}),870,750)!=null);check(ControllerFocus.near(Arrays.asList(new int[]{800,712,1124,880,350}),270,750)!=null);System.out.println(checks+" controller focus regressions passed");}
}
